import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const ApprovedSellersLayer = () => {
  const [sellers, setSellers] = useState([]);
  const [loading, setLoading] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [docStatusFilter, setDocStatusFilter] = useState("All");
  const [selectedSeller, setSelectedSeller] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const itemsPerPage = 10;
  const navigate = useNavigate();

  const handleView = (seller) => {
    setSelectedSeller(seller);
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setSelectedSeller(null);
  };

  const paginate = (pageNumber) => {
    if (pageNumber >= 1 && pageNumber <= totalPages) {
      fetchApprovedSeller(pageNumber, docStatusFilter);
    }
  };

  const fetchApprovedSeller = async (page = 1, status = docStatusFilter) => {
    setLoading(true);
    try {
      const response = await axios.get(
        `${process.env.REACT_APP_BACKEND_URL}/api/sellers/approvedSellers?page=${page}&limit=${itemsPerPage}&docStatus=${encodeURIComponent(status)}`
      );
      if (response.data.success) {
        setSellers(response.data.sellers);
        setTotalPages(response.data.pagination.totalPages);
        setCurrentPage(response.data.pagination.currentPage);
        if (typeof response.data.pendingDocsCount === "number") {
          window.dispatchEvent(
            new CustomEvent("sellerDocStatusChanged", {
              detail: { pendingDocsCount: response.data.pendingDocsCount },
            })
          );
        }
      } else {
        setSellers(response.data);
      }
    } catch (error) {
      console.error("Error fetching approved sellers:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchApprovedSeller(1, docStatusFilter);
  }, []);

  const handleDocStatusChange = (status) => {
    setDocStatusFilter(status);
    setCurrentPage(1);
    fetchApprovedSeller(1, status);
  };

  const categoryNameMap = {
    medicines: "Medicines & Cosmetics",
    medicalDevicesAndSurgicalEquipment: "Medical Devices & Surgical Equipment",
    healthSupplements: "Health Supplements",
    petCare: "Pet Care",
    veterinaryProducts: "Pet Care",
    skinAndHairCare: "Skin & Hair Care",
  };

  const getPendingCategoryNames = (seller) => {
    if (!seller || !seller.categoryDocuments) return [];
    const categoryDocs = seller.categoryDocuments;
    const names = [];

    Object.keys(categoryDocs).forEach((key) => {
      if (key === "veterinaryProducts" && categoryDocs.petCare?.documents?.length > 0) {
        return;
      }
      const catData = categoryDocs[key];
      if (!catData) return;

      const hasDocs = Array.isArray(catData.documents) && catData.documents.length > 0;
      if (!hasDocs) return false;

      const catStatus = (catData.status || "").trim().toLowerCase();
      const hasPendingDoc = catData.documents.some(
        (doc) => (doc?.status || "").trim().toLowerCase() === "pending"
      );

      if (catStatus === "pending" || hasPendingDoc) {
        const displayName = categoryNameMap[key] || key.replace(/([A-Z])/g, " $1").trim();
        if (!names.includes(displayName)) {
          names.push(displayName);
        }
      }
    });

    return names;
  };

  return (
    <div className="dashboard-body__content">
      <div className="card common-card border border-gray-five">
        <div className="card-body">
          <div className="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-3">
            <h4 style={{ margin: 0 }}>Approved Sellers</h4>

            {/* Doc. Status Filter */}
            <div className="d-flex align-items-center gap-2">
              <label
                htmlFor="docStatusSelect"
                className="text-muted fw-semibold small mb-0"
                style={{ fontSize: "13px", whiteSpace: "nowrap" }}
              >
                Doc. Status:
              </label>
              <select
                id="docStatusSelect"
                className="form-select form-select-sm"
                value={docStatusFilter}
                onChange={(e) => handleDocStatusChange(e.target.value)}
                style={{
                  width: "150px",
                  borderRadius: "6px",
                  borderColor: docStatusFilter !== "All" ? "#F59E0B" : "#CBD5E1",
                  backgroundColor: docStatusFilter === "Pending" ? "#FFFBEB" : "#FFFFFF",
                  color: docStatusFilter === "Pending" ? "#92400E" : "#1E293B",
                  fontWeight: "600",
                  cursor: "pointer",
                  padding: "6px 12px",
                }}
              >
                <option value="All">All</option>
                <option value="Pending">Pending</option>
                <option value="Approved">Approved</option>
              </select>
            </div>
          </div>
          {loading ? (
            <p>Loading sellers...</p>
          ) : (
            <div className="table-responsive" style={{ marginTop: "-20px" }}>
              <table className="table text-body">
                <thead>
                  <tr>
                    <th>SN.</th>
                    <th>Seller Name</th>
                    <th>Email</th>
                    <th>Phone</th>
                    <th>Pending Docs</th>
                    <th className="text-center">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {sellers && sellers.length > 0 ? (
                    sellers.map((seller, index) => {
                      const pendingCategories = getPendingCategoryNames(seller);
                      const isPendingDocs = pendingCategories.length > 0;
                      return (
                        <tr
                          key={seller._id || index}
                          className={isPendingDocs ? "table-warning" : ""}
                          style={isPendingDocs ? { backgroundColor: "#FFFBEB" } : undefined}
                        >
                          <td style={isPendingDocs ? { backgroundColor: "#FFFBEB", borderLeft: "4px solid #F59E0B" } : undefined}>
                            {(currentPage - 1) * itemsPerPage + index + 1}
                          </td>
                          <td style={isPendingDocs ? { backgroundColor: "#FFFBEB" } : undefined}>
                            <span className="fw-semibold text-dark" style={{ fontSize: "14px" }}>
                              {seller?.basicInformation?.shopName || "N/A"}
                            </span>
                          </td>
                          <td style={isPendingDocs ? { backgroundColor: "#FFFBEB" } : undefined}>
                            {seller?.contactInformation?.emailAddress || "N/A"}
                          </td>
                          <td style={isPendingDocs ? { backgroundColor: "#FFFBEB" } : undefined}>
                            {seller?.contactInformation?.Mobileprimary || "N/A"}
                          </td>
                          <td style={isPendingDocs ? { backgroundColor: "#FFFBEB" } : undefined}>
                            {pendingCategories.length > 0 ? (
                              <div className="d-flex flex-column gap-1 align-items-start">
                                {pendingCategories.map((catName, cIdx) => (
                                  <span
                                    key={cIdx}
                                    className="badge"
                                    style={{
                                      backgroundColor: "#FEF3C7",
                                      color: "#92400E",
                                      border: "1px solid #FCD34D",
                                      fontSize: "11px",
                                      fontWeight: "600",
                                      padding: "3px 8px",
                                      borderRadius: "8px",
                                      whiteSpace: "nowrap",
                                      textAlign: "left",
                                      lineHeight: "1.3"
                                    }}
                                  >
                                    {catName}
                                  </span>
                                ))}
                              </div>
                            ) : (
                              <span className="text-muted" style={{ fontSize: "13px" }}>-</span>
                            )}
                          </td>
                          <td className="text-center" style={isPendingDocs ? { backgroundColor: "#FFFBEB" } : undefined}>
                            <div className="d-flex justify-content-center gap-2 mt-2">
                              <button
                                className="btn btn-sm btn-info text-white"
                                style={{ backgroundColor: "blue", border: "none" }}
                                onClick={() => navigate(`/seller-under-approval/${seller._id}`)}
                              >
                                View
                              </button>
                            </div>
                          </td>
                        </tr>
                      );
                    })
                  ) : (
                    <tr>
                      <td colSpan="6" className="text-center">No approved sellers found.</td>
                    </tr>
                  )}
                </tbody>
              </table>

              {/* Pagination Controls */}
              {totalPages > 1 && (
                <div className="d-flex justify-content-center mt-4 mb-3">
                  <nav>
                    <ul className="pagination mb-0">
                      <li className={`page-item ${currentPage === 1 ? 'disabled' : ''}`}>
                        <button className="page-link" onClick={() => paginate(currentPage - 1)} disabled={currentPage === 1}>
                          Previous
                        </button>
                      </li>
                      {[...Array(totalPages)].map((_, index) => (
                        <li key={index + 1} className={`page-item ${currentPage === index + 1 ? 'active' : ''}`}>
                          <button className="page-link" onClick={() => paginate(index + 1)}>
                            {index + 1}
                          </button>
                        </li>
                      ))}
                      <li className={`page-item ${currentPage === totalPages ? 'disabled' : ''}`}>
                        <button className="page-link" onClick={() => paginate(currentPage + 1)} disabled={currentPage === totalPages}>
                          Next
                        </button>
                      </li>
                    </ul>
                  </nav>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Seller Details Modal */}
      {showModal && selectedSeller && (
        <div className="modal show d-block" style={{ backgroundColor: "rgba(0,0,0,0.5)" }} tabIndex="-1">
          <div className="modal-dialog modal-lg modal-dialog-centered">
            <div className="modal-content">
              <div className="modal-header bg-dark text-white">
                <h5 className="modal-title text-white">Seller Details</h5>
                <button type="button" className="btn-close btn-close-white" onClick={closeModal} aria-label="Close"></button>
              </div>
              <div className="modal-body">
                <div className="row">
                  <div className="col-md-6 mb-3">
                    <h6 className="fw-bold mb-1">Shop Name</h6>
                    <p className="mb-3">{selectedSeller.basicInformation?.shopName || "N/A"}</p>

                    <h6 className="fw-bold mb-1">Email</h6>
                    <p className="mb-3">{selectedSeller.contactInformation?.emailAddress || "N/A"}</p>

                    <h6 className="fw-bold mb-1">Phone</h6>
                    <p className="mb-3">{selectedSeller.contactInformation?.Mobileprimary || "N/A"}</p>

                    <h6 className="fw-bold mb-1">Landline</h6>
                    <p className="mb-3">{selectedSeller.contactInformation?.landlineNumber || "Landline not available"}</p>

                    <h6 className="fw-bold mb-1">Address</h6>
                    <p className="mb-3">
                      {selectedSeller.basicInformation?.addressLine1}
                      {selectedSeller.basicInformation?.addressLine2 && `, ${selectedSeller.basicInformation?.addressLine2}`}
                    </p>

                    <h6 className="fw-bold mb-1">ZIP Code</h6>
                    <p className="mb-3">{selectedSeller.basicInformation?.pincode || "N/A"}</p>

                    <h6 className="fw-bold mb-1">City</h6>
                    <p className="mb-3">{selectedSeller.basicInformation?.city || "N/A"}</p>
                  </div>

                  <div className="col-md-6 mb-3">
                    <h6 className="fw-bold mb-1">Authorized Person</h6>
                    <p className="mb-3">Name: {selectedSeller.basicInformation?.contactPersonName || "N/A"}</p>

                    <h6 className="fw-bold mb-1">GSTIN</h6>
                    <p className="mb-3">{selectedSeller.basicInformation?.gstin || "N/A"}</p>

                    <h6 className="fw-bold mb-1">PAN Number</h6>
                    <p className="mb-3">{selectedSeller.basicInformation?.panNumber || "N/A"}</p>

                    <h6 className="fw-bold mb-1">Documents</h6>
                    {selectedSeller.documents && selectedSeller.documents.length > 0 ? (
                      <ul className="list-unstyled mb-3">
                        {selectedSeller.documents.map((doc, idx) => (
                          <li key={idx} className="mb-1">
                            {doc.documentName} -{" "}
                            <a href={doc.documentUrl} target="_blank" rel="noopener noreferrer" className="text-primary text-decoration-none">
                              View Document
                            </a>
                          </li>
                        ))}
                      </ul>
                    ) : (
                      <p className="mb-3">No documents available</p>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ApprovedSellersLayer;
